RATE = {
    "eleven_multilingual_v2": 1.0,
    "eleven_v3": 1.0,
    "eleven_turbo_v2_5": 0.5,
    "eleven_flash_v2_5": 0.5,
}

PLAN_CREDITS = {"free": 10_000, "starter": 30_000, "creator": 100_000,
                "pro": 500_000, "scale": 2_000_000}

ACCEPT = {"mp3": "audio/mpeg", "pcm": "audio/pcm", "ulaw": "audio/basic"}

MAX_REQUEST_CHARS = 5000
BASE = "https://api.elevenlabs.io/v1/text-to-speech"


def credits(text, model_id):
    if model_id not in RATE:
        raise ValueError(f"unknown model {model_id!r}")
    return len(text) * RATE[model_id]


def fits_plan(text, model_id, plan):
    if plan not in PLAN_CREDITS:
        raise ValueError(f"unknown plan {plan!r}")
    return credits(text, model_id) <= PLAN_CREDITS[plan]


def chunk_text(text, limit=MAX_REQUEST_CHARS):
    words = text.split()
    chunks = []
    current = ""
    for word in words:
        if len(word) > limit:
            raise ValueError(f"a single word exceeds the {limit}-character limit")
        candidate = word if not current else current + " " + word
        if len(candidate) > limit:
            chunks.append(current)
            current = word
        else:
            current = candidate
    if current:
        chunks.append(current)
    return chunks


def build_request(voice_id, text, model_id, voice_settings=None,
                  output_format="mp3_44100_128", api_key="$ELEVENLABS_API_KEY"):
    if model_id not in RATE:
        raise ValueError(f"unknown model {model_id!r}")
    if len(text) > MAX_REQUEST_CHARS:
        raise ValueError(
            f"text is {len(text)} characters; split it into chunks of at most "
            f"{MAX_REQUEST_CHARS}")
    family = output_format.split("_")[0]
    if family not in ACCEPT:
        raise ValueError(f"unknown output format {output_format!r}")
    settings = {"stability": 0.5, "similarity_boost": 0.75, "style": 0.0,
                "use_speaker_boost": True}
    settings.update(voice_settings or {})
    for name in ("stability", "similarity_boost", "style"):
        value = settings[name]
        if not 0.0 <= value <= 1.0:
            raise ValueError(f"{name} must be between 0 and 1, got {value}")
    return {
        "method": "POST",
        "url": f"{BASE}/{voice_id}?output_format={output_format}",
        "headers": {"xi-api-key": api_key,
                    "Content-Type": "application/json",
                    "Accept": ACCEPT[family]},
        "body": {"text": text, "model_id": model_id, "voice_settings": settings},
    }
